head.script:
            // 직접 저장 여부

///////// 2. 초기화 영역 /////////
            scwin.onpageload = function() {

                scwin.vScrenID = "ULDTMS03080.xml";
///////// 1. 변수 및 선언 영역 /////////
scwin.directYn = "N";
                dma_search.set("formCd", $c.data.getParameter("formCd"));
                dma_search.set("formVer", $c.data.getParameter("formVer"));
                dma_search.set("wrtrptMaindocTpCd", "2");

                scwin.directYn = $c.data.getParameter("directYn");
                // 전체/할당 목록 조회
                scwin.fnSearch();
            };

///////// 3. 컴포넌트 이벤트 영역 /////////
            scwin.btn_save_onclick = function (e) {

                // 웹스퀘어가 필터링 처리된 데이타는 못찾는 문제로 저장시에 필터 해제
                dlt_list2.clearFilter();
                const list = [];
                if (scwin.directYn === "Y") {
                    let params = {};
                    params.refreshYn = "Y";

                    for (let i=0; i < dlt_list2.getRowCount(); i++) {
                        if (dlt_list2.getRowStatus(i) !== "D") {
                            const params = {};
                            params.formCd = dlt_list2.getCellData(i, "formCd");
                            params.formVer = dlt_list2.getCellData(i, "formVer");
                            params.formKorNm = dlt_list2.getCellData(i, "formKorNm");

                            list.push(params);
                        }
                    }
                    params.list = list;

                    $c.win.closePopup(params);
                } else {
                    const subList = [];
                    for (let i=0; i < dlt_list2.getRowCount(); i++) {                    
                        if (dlt_list2.getRowStatus(i) !== "D") {                            
                            list.push(dlt_list2.getCellData(i, "formCd"));
                            subList.push("2");
                        }
                    }
                    dma_save.set("formCd", dma_search.get("formCd"));
                    dma_save.set("formVer", dma_search.get("formVer"));
                    dma_save.set("wrtrptMaindocTpCd", "2");
                    dma_save.set("byFormDepCds", list);
                    dma_save.set("formMandtryTpCds", subList);

                    $c.sbm.execute(sbm_save, dma_save.getJSON());
                }
            };

            scwin.btn_right_onclick = function (e) {

                let count_ = 0;
                for (let i=dlt_list1.getRowCount(); i > -1; i--) {
                    if (dlt_list1.getCellData(i, "CHK") === "1") {
                        if (dlt_list1.getRowStatus(i) === "C") {
                            dlt_list2.undeleteRow(dlt_list1.getCellData(i, "selIndex"));
                            dlt_list1.removeRow(i);
                        } else {
                            // 할당된 목록에 추가
                            dlt_list2.insertRow(dlt_list2.getRowCount());
                            dlt_list2.setCellData(dlt_list2.getRowCount()-1, "formCd", dlt_list1.getCellData(i, "formCd"));
                            dlt_list2.setCellData(dlt_list2.getRowCount()-1, "formVer", dlt_list1.getCellData(i, "formVer"));
                            dlt_list2.setCellData(dlt_list2.getRowCount()-1, "formCdKorNm", dlt_list1.getCellData(i, "formCdKorNm"));
                            dlt_list2.setCellData(dlt_list2.getRowCount()-1, "formKorNm", dlt_list1.getCellData(i, "formKorNm"));
                            dlt_list2.setCellData(dlt_list2.getRowCount()-1, "selIndex", i);                                                            

                            dlt_list1.setCellData(i, "CHK", "0");
                            dlt_list1.deleteRow(i);
                        }                                                
                        count_++;
                    }
                }

                // 체크가 되어 있는 항목이 있는 여부 확인
                if (count_ < 1) {
                    $c.win.alert("전체 목록에 추가 할 첨부 문서 정보를 체크해 주세요.");
                }                
            };

            scwin.btn_left_onclick = function (e) {

                let count_ = 0;
                for (let i=dlt_list2.getRowCount(); i > -1; i--) {
                    if (dlt_list2.getCellData(i, "CHK") === "1") {
                        if (dlt_list2.getRowStatus(i) === "C") {
                            dlt_list1.undeleteRow(dlt_list2.getCellData(i, "selIndex"));
                            dlt_list2.removeRow(i);
                        } else {
                            dlt_list1.insertRow(dlt_list1.getRowCount());                            
                            dlt_list1.setCellData(dlt_list1.getRowCount()-1, "formCd", dlt_list2.getCellData(i, "formCd"));
                            dlt_list1.setCellData(dlt_list1.getRowCount()-1, "formVer", dlt_list2.getCellData(i, "formVer"));
                            dlt_list1.setCellData(dlt_list1.getRowCount()-1, "formCdKorNm", dlt_list2.getCellData(i, "formCdKorNm"));
                            dlt_list1.setCellData(dlt_list1.getRowCount()-1, "formKorNm", dlt_list2.getCellData(i, "formKorNm"));
                            dlt_list1.setCellData(dlt_list1.getRowCount()-1, "selIndex", i);                        

                            dlt_list2.setCellData(i, "CHK", "0");
                            dlt_list2.deleteRow(i);
                        }                        
                        count_++;
                    }
                }

                // 체크가 되어 있는 항목이 있는 여부 확인
                if (count_ < 1) {
                    $c.win.alert("할당된 목록에 삭제 할 첨부 문서 정보를 체크해 주세요.");
                }
            };

            scwin.ibx_search1_onkeyup = function (e) {

                $c.tms.setDataListFilter(dlt_list1, ["formCdKorNm"], ibx_search1.getValue());
            };

            scwin.ibx_search2_onkeyup = function (e) {

                $c.tms.setDataListFilter(dlt_list2, ["formCdKorNm"], ibx_search2.getValue());
            };

            scwin.btn_close_onclick = function (e) {

                $c.win.closePopup();
            };

///////// 4. 서브미션 콜백 영역 /////////
            scwin.sbm_detail_submitdone = function (e) {

                // 조회 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    // 강제적으로 화면용 데이타 생성
                    for (let i=0; i < dlt_list2.getRowCount(); i++) {
                        dlt_list2.setCellData(i, "formCdKorNm", dlt_list2.getCellData(i, "formCd") + " - " + dlt_list2.getCellData(i, "formKorNm"));
                    }
                } else {
                    $c.win.alert(result.message);
                }                
            };

            scwin.sbm_save_submitdone = async function (e) {

                // 저장 성공인 경우
                const result = e.responseJSON;
                if (result.success) {
                    await $c.win.alert("저장되었습니다.");

                    let params = {};
                    params.refreshYn = "Y";                    

                    $c.win.closePopup(params);
                } else {
                    $c.win.alert(result.message);                    
                }                
            };

///////// 5. 일반/업무 함수 영역 /////////
            scwin.fnSearch = function () {

                $c.sbm.execute(sbm_detail, dma_search.getJSON());
            };
